from collections import Counter
class Solution:
    def minimumOperations(self, nums):
        def top2(vals):
            mc = Counter(vals).most_common(2)
            return (mc[0][1] if mc else 0, mc[1][1] if len(mc) > 1 else 0)
        te, se = top2(nums[0::2])
        to, so = top2(nums[1::2])
        n = len(nums)
        if te != to:
            return n - te - to
        return n - max(te + so, se + to)

