class Solution {
    private int[] top2(List<Integer> v) {
        Map<Integer, Integer> c = new HashMap<>();
        for (int x : v) c.merge(x, 1, Integer::sum);
        int a = 0, b = 0;
        for (int f : c.values()) {
            if (f > a) { b = a; a = f; }
            else if (f > b) b = f;
        }
        return new int[]{a, b};
    }
    public int minimumOperations(int[] nums) {
        List<Integer> ev = new ArrayList<>(), od = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) (i % 2 == 0 ? ev : od).add(nums[i]);
        int[] e = top2(ev), o = top2(od);
        int n = nums.length;
        if (e[0] != o[0]) return n - e[0] - o[0];
        return n - Math.max(e[0] + o[1], e[1] + o[0]);
    }
}

