            if (f > a) { b = a; a = f; } else if (f > b) b = f;
        }
        return [a, b];
    };
    const [te, se] = top2(nums.filter((_, i) => i % 2 === 0));
    const [to, so] = top2(nums.filter((_, i) => i % 2 === 1));
    const n = nums.length;
    if (te !== to) return n - te - to;
    return n - Math.max(te + so, se + to);
};

