class Solution {
    public int minimumOperations(int[] nums) {
        Map<Integer, Integer> ce = new HashMap<>(), co = new HashMap<>();
        for (int i = 0; i < nums.length; i++) (i % 2 == 0 ? ce : co).merge(nums[i], 1, Integer::sum);
        List<Integer> fe = new ArrayList<>(ce.values()), fo = new ArrayList<>(co.values());
        fe.sort(Collections.reverseOrder()); fo.sort(Collections.reverseOrder());
        fe.add(0); fo.add(0);
        int n = nums.length;
        if (!fe.get(0).equals(fo.get(0))) return n - fe.get(0) - fo.get(0);
        return n - Math.max(fe.get(0) + fo.get(1), fe.get(1) + fo.get(0));
    }
}

